import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import styles from './LoginPage.module.css';

const LoginPage = () => {
    const navigate = useNavigate();
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const theme = localStorage.getItem('theme') || 'light';
    const logoSrc = theme === 'dark' ? '/assets/images/logo.png' : '/assets/images/logo_t.png';

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            const result = await login(email, password);

            if (result && result.success === false) {
                setError(result.message || 'Ошибка входа');
                setLoading(false);
                return;
            }

            setError('');
            navigate('/');
        } catch (err) {
            let errorMessage = 'Неверный email или пароль';
            if (err.response?.data?.message) {
                errorMessage = err.response.data.message;
            } else if (err.message) {
                errorMessage = err.message;
            }
            setError(errorMessage);
            setLoading(false);
        }
    };

    const handleEmailChange = (e) => {
        setEmail(e.target.value);
        if (error) setError('');
    };

    const handlePasswordChange = (e) => {
        setPassword(e.target.value);
        if (error) setError('');
    };

    return (
        <div className={styles.loginPage}>
            <div className={styles.container}>
                <div className={styles.loginCard}>
                    <div className={styles.header}>
                        <img src={logoSrc} alt="Volley Hub" className={styles.logo} />
                        <h1 className={styles.title}>Вход в аккаунт</h1>
                        <p className={styles.subtitle}>Добро пожаловать обратно!</p>
                    </div>

                    <form onSubmit={handleSubmit} className={styles.form}>
                        {error && <div className={styles.errorMessage}>{error}</div>}

                        <Input
                            label="Email"
                            type="email"
                            placeholder="Введите ваш email"
                            value={email}
                            onChange={handleEmailChange}
                            required
                        />

                        <PasswordInput
                            label="Пароль"
                            placeholder="Введите пароль"
                            value={password}
                            onChange={handlePasswordChange}
                            required
                        />

                        <Button type="submit" fullWidth size="large" loading={loading}>
                            Войти
                        </Button>
                    </form>

                    <div className={styles.footer}>
                        <p className={styles.registerLink}>
                            Нет аккаунта? <a href="/register">Зарегистрироваться</a>
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;
